// src/components/AnalyticsDashboard.tsx

import React, { useEffect, useState } from "react";
import axios from "axios";
import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  Tooltip as ReTooltip,
  PieChart,
  Pie,
  Cell,
  Legend as ReLegend,
  BarChart,
  Bar
} from "recharts";

// 1️⃣ Define your data types
interface Delivery {
  _id: string;
  customerId: string;
  driverId?: string;
  status: "Assigned" | "Pending" | "In Transit" | "Delivered";
  duration?: number;     // in minutes
  createdAt: string;     // ISO timestamp
}

interface Driver {
  _id: string;
  name: string;
}

interface Summary {
  total: number;
  completed: number;
  pending: number;
  inTransit: number;
  successRate: string;
  avgTime: string;
}

interface StatusData {
  name: string;
  value: number;
}

interface TrendData {
  date: string;
  count: number;
}

interface DriverData {
  driver: string;
  count: number;
}

export default function AnalyticsDashboard() {
  // 2️⃣ State with proper types
  const [summary, setSummary] = useState<Summary>({
    total: 0,
    completed: 0,
    pending: 0,
    inTransit: 0,
    successRate: "0%",
    avgTime: "0"
  });

  const [statusData, setStatusData]     = useState<StatusData[]>([]);
  const [trendData, setTrendData]       = useState<TrendData[]>([]);
  const [driverData, setDriverData]     = useState<DriverData[]>([]);

  // 3️⃣ Fetch data & compute metrics
  useEffect(() => {
    async function fetchStats() {
      try {
        const [deliveriesRes, driversRes] = await Promise.all([
          axios.get<Delivery[]>("/api/delivery"),
          axios.get<Driver[]>("/api/drivers")
        ]);

        const deliveries = deliveriesRes.data;
        const total      = deliveries.length;
        const completed  = deliveries.filter((d) => d.status === "Delivered").length;
        const pending    = deliveries.filter((d) => d.status === "Pending").length;
        const inTransit  = deliveries.filter((d) => d.status === "In Transit").length;

        // Average delivery time
        const avgMins = total > 0
          ? deliveries.reduce((sum, d) => sum + (d.duration || 0), 0) / total
          : 0;
        const avgTime = avgMins.toFixed(1);

        setSummary({
          total,
          completed,
          pending,
          inTransit,
          successRate: total > 0 ? `${Math.round((completed / total) * 100)}%` : "0%",
          avgTime
        });

        // Status distribution
        setStatusData([
          { name: "Delivered",   value: completed },
          { name: "In Transit",  value: inTransit },
          { name: "Pending",     value: pending }
        ]);

        // Trend by day
        const byDateMap: Record<string, number> = {};
        deliveries.forEach((d) => {
          const day = d.createdAt.slice(0, 10);
          byDateMap[day] = (byDateMap[day] || 0) + 1;
        });
        setTrendData(
          Object.entries(byDateMap).map(([date, count]) => ({ date, count }))
        );

        // Driver utilization
        const driverCountMap: Record<string, number> = {};
        deliveries.forEach((d) => {
          if (d.status === "Delivered" && d.driverId) {
            driverCountMap[d.driverId] = (driverCountMap[d.driverId] || 0) + 1;
          }
        });
        setDriverData(
          Object.entries(driverCountMap).map(([driver, count]) => ({ driver, count }))
        );

      } catch (err) {
        console.error("Failed to fetch analytics data", err);
      }
    }
    fetchStats();
  }, []);

  const COLORS = ["#28a745", "#ffc107", "#dc3545"];

  return (
    <div style={{ padding: 20, fontFamily: "Arial, sans-serif" }}>
      {/* Summary cards */}
      <div style={{ display: "flex", gap: 20, marginBottom: 40 }}>
        {[
          { label: "Total Deliveries", value: summary.total },
          { label: "Completed",        value: summary.completed },
          { label: "Pending",          value: summary.pending },
          { label: "In Transit",       value: summary.inTransit },
          { label: "Success Rate",     value: summary.successRate },
          { label: "Avg Delivery Time (m)", value: summary.avgTime }
        ].map((card, i) => (
          <div
            key={i}
            style={{
              flex: 1,
              padding: 20,
              background: "#fff",
              borderRadius: 8,
              boxShadow: "0 2px 8px rgba(0,0,0,0.1)"
            }}
          >
            <h4 style={{ margin: 0, color: "#555" }}>{card.label}</h4>
            <p style={{ fontSize: 24, fontWeight: "bold", margin: "8px 0 0" }}>
              {card.value}
            </p>
          </div>
        ))}
      </div>

      <div style={{ display: "flex", gap: 40, marginBottom: 40 }}>
        {/* Status distribution */}
        <ResponsiveContainer width="30%" height={300}>
          <PieChart>
            <Pie
              data={statusData}
              dataKey="value"
              nameKey="name"
              innerRadius={60}
              outerRadius={100}
              label
            >
              {statusData.map((_, idx) => (
                <Cell key={idx} fill={COLORS[idx]} />
              ))}
            </Pie>
            <ReTooltip/>
            <ReLegend verticalAlign="bottom" height={36}/>
          </PieChart>
        </ResponsiveContainer>

        {/* Trend line */}
        <ResponsiveContainer width="70%" height={300}>
          <LineChart data={trendData}>
            <XAxis dataKey="date" />
            <YAxis />
            <ReTooltip/>
            <Line type="monotone" dataKey="count" stroke="#007bff" strokeWidth={2} />
          </LineChart>
        </ResponsiveContainer>
      </div>

      {/* Driver utilization */}
      <div>
        <h3>Driver Utilization</h3>
        <ResponsiveContainer width="100%" height={300}>
          <BarChart data={driverData}>
            <XAxis dataKey="driver" />
            <YAxis />
            <ReTooltip/>
            <Bar dataKey="count" fill="#28a745" />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}
